  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Pethidine, a 4-phenylpiperidine opioid structurally closest to the query's piperidine opioid core, has an absolute oral bioavailability of 0.52 (47-61%) in healthy subjects, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Encainide, which shares a piperidine, amide, and aromatic ether architecture with the query, has an absolute oral bioavailability of 32 ± 7% in normal subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Ziprasidone, a piperazine-based CNS drug with heteroaromatic character, has an absolute oral bioavailability of about 60% in the fed state, supporting high oral bioavailability for a lipophilic basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Tenidap, a thiophene-containing drug, has an absolute oral bioavailability of 85%, indicating that the query's thiophene moiety is not inherently bioavailability-limiting.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Meptazinol, an opioid analgesic, has low absolute oral bioavailability (4.5-8.7%) due to extensive first-pass metabolism, but its phenolic azepine structure and conjugation pathway differ from the query's fentanyl-like amide piperidine, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a fentanyl-like 4-aminopiperidine amide. The closest high-transfer analogue, pethidine, has ~52% absolute oral bioavailability, and other piperidine/amide/heteroaromatic drugs (encainide ~32%, ziprasidone ~60%, tenidap ~85%) support F >= 20%. The only low-F opioid, meptazinol, is a phenolic azepine with extensive first-pass conjugation and is less structurally transferable. Overall evidence favors high oral bioavailability.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the exact query molecule or fentanyl itself in the provided evidence.",
    "First-pass metabolism and transporter involvement for the 4-methoxymethyl and thienylethyl modifications are uncharacterized.",
    "Food effects and formulation dependence for the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

